SELECT ss.id, ss.title, ss.cover, ss.summary, CASE WHEN r1.level = 1 THEN r1.name WHEN r1.level = 2 THEN r2.name WHEN r1.level >= 3 THEN r3.name END AS county_name, CASE WHEN r1.level = 1 THEN NULL WHEN r1.level = 2 THEN r1.name WHEN r1.level >= 3 THEN r2.name END AS town_name, CASE WHEN r1.level >= 3 THEN r1.name ELSE NULL END AS village_name, GROUP_CONCAT(DISTINCT c.name) AS category_names FROM scenic_spot ss LEFT JOIN region r1 ON r1.id = ss.region_id LEFT JOIN region r2 ON r2.id = r1.parent_id LEFT JOIN region r3 ON r3.id = r2.parent_id LEFT JOIN scenic_spot_category ssc ON ssc.scenic_spot_id = ss.id LEFT JOIN category c ON c.id = ssc.category_id
AND ss.title LIKE concat('%',#{title},'%')
AND ss.region_id IN
#{regionId}
AND ss.create_time BETWEEN #{startTime} AND #{endTime}
AND ss.id IN
#{id}
GROUP BY ss.id ORDER BY ss.id DESC
LIMIT #{current},#{size}

SELECT COUNT(*)
FROM scenic_spot ss


        AND ss.title LIKE concat('%',#{title},'%')


        AND ss.region_id IN

            #{regionId}




        AND ss.create_time BETWEEN #{startTime} AND #{endTime}


        AND ss.id IN

            #{id}
